type Set[T](items: [T]):
    fn add(inout self, item: T):
        self.items.append(item)

    fn contains(self, v: T) -> bool:
        return v in self.items

    fn & (self, other: Set[T]) -> Set[T]:
        var new = Set[T]()
        for v in self.items:
            if other.contains(v):
                new.add(v)
        return new

    fn | (self, other: Set[T]) -> Set[T]:
        var new = Set[T]()
        for v in self.items:
            new.add(v)
        for v in other.items:
            new.add(v)
        return new

    fn & (self, other: Set[T]) -> Set[T]:
        return self & other

    fn -(self, other: Set[T]) -> Set[T]:
