fn triangle_area(a: int, b: int, c: int) -> f64:
    """
    Given the lengths of the three sides of a triangle. Return the area of
    the triangle rounded to 2 decimal points if the three sides form a valid triangle. 
    Otherwise return -1
    Three sides make a valid triangle when the sum of any two sides is greater 
    than the third side.
    """
    fn semi_perimeter(a: f64, b: f64, c: f64) -> f64:
        return (a + b + c) / 2

    fn heron_formula(a: f64, b: f64, c: f64) -> f64:
        return sqrt(semi_perimeter(a, b, c) * (semi_perimeter(a, b, c) - a) * (semi_perimeter(a, b, c) - b) * (semi_perimeter(a, b, c) - c))

    fn is_valid_triangle(a: int, b: int, c: int) -> bool:
        return (a + b > c) and (a + c > b) and (b + c > a)

    fn area(a: int, b: int, c: int) -> f64:
        if is_valid_triangle(a, b, c):
            return round(heron_formula(a, b, c), 2)
        else:
            return -1

    return area(a, b, c)

