fn lcs_of_three(X: str, Y: str, Z: str) -> int:
    fn lcs(X: str, Y: str) -> int:
        m = len(X)
        n = len(Y)
        dp: [int] = [0] * (n + 1)
        for i in range(1, m + 1):
            prev = dp
            dp = [0] * (n + 1)
            for j in range(1, n + 1):
                if X[i - 1] == Y[j - 1]:
                    dp[j] = prev[j - 1] + 1
                else:
                    dp[j] = max(prev[j], dp[j - 1])
        return dp[n]
    return lcs(X, Y)

