    n = len(Y) + 1
    o = len(Z) + 1
    dp: [[int]] = [[0 for _ in range(o)] for _ in range(n)]
    for i in range(1, m):
        for j in range(1, n):
            for k in range(1, o):
                if X[i - 1] == Y[j - 1] == Z[k - 1]:
                    dp[j][k] = dp[j - 1][k - 1] + 1
                else:
                    dp[j][k] = max(dp[j - 1][k], dp[j][k - 1])
    return dp[n - 1][o - 1]

