    Find the last position of an element in a sorted array.
    """
    var l = 0
    var r = len(arr) - 1
    while l <= r:
        var m = (l + r) / 2
        if arr[m] == x:
            if m == len(arr) - 1 or arr[m + 1] != x:
                return m
            l = m + 1
        elif arr[m] < x:
            l = m + 1
        else:
            r = m - 1
    return -1

